<?php
require_once __DIR__.'/exam_question_language.php';
function questionCorrectionContentUrl(array $q,bool $edit=false):string {
    $file=($q['bank_kind']??'learning')==='exam'?($q['type']==='MCQ'?'exam_mcqs.php':'exam_questions.php'):'questions.php';
    return schoolRouteUrl('modules/learning/'.$file,$edit?['view'=>'edit','question_id'=>$q['id'],'bank_ui'=>'1']:['record_id'=>$q['id'],'bank_ui'=>'1']);
}
function questionCorrectionRichCard(PDO $db,array $q,string $heading):void {
    $q=questionCorrectionSnapshot($q);$c=$db->prepare('SELECT name FROM classes WHERE id=?');$c->execute([$q['class_id']]);$s=$db->prepare('SELECT name_en FROM subjects WHERE id=?');$s->execute([$q['subject_id']]);
    ?>
    <section class="card card-body mb-3 exam-question-list"><h2 class="h5"><?= sanitize($heading) ?></h2><p class="small text-muted"><?= sanitize(($q['bank_kind']==='exam'?'Exam Questions':'Question Bank').' · '.$c->fetchColumn().' · '.subjectCanonicalName((string)$s->fetchColumn()).' · '.$q['chapter'].' · '.$q['type'].' · '.($q['marks']??'0').' marks') ?></p>
    <?php if($q['bank_kind']!=='exam'&&($q['catalog_topic_id']??$q['topic_id'])): $t=$db->prepare('SELECT name FROM topics WHERE id=?');$t->execute([$q['catalog_topic_id']??$q['topic_id']]); ?><p class="small">Topic: <?= sanitize((string)$t->fetchColumn()) ?></p><?php endif; ?>
    <div class="exam-bank-rich exam-bank-question"><?= examQuestionRich($q['question_text'],$q['question_text_np'],'both',true) ?></div>
    <?php if($q['type']==='MCQ'): foreach(['A','B','C','D'] as $letter): ?><div class="exam-bank-rich mb-2"><strong><?= $letter ?>.</strong> <?= examQuestionRich($q['options'][$letter],$q['options_np'][$letter],'both') ?></div><?php endforeach; ?><p>Correct option: <?= sanitize($q['correct_option']) ?></p><?php endif; ?>
    <h3 class="h6">Model answer</h3><div class="exam-bank-rich"><?= examQuestionRich($q['answer'],$q['answer_np'],'both') ?></div></section>
<?php }
function questionCorrectionFilters(PDO $db,bool $admin,array $filters,array $pagination,string $route,callable $url):void { ?>
    <nav class="nav nav-pills gap-2 mb-3" aria-label="Correction banks"><?php foreach(['learning'=>'Question Bank','exam'=>'Exam Questions'] as $key=>$title): ?><a class="nav-link <?= $filters['bank_kind']===$key?'active':'' ?>" href="<?= sanitize($url(['bank_kind'=>$key,'page'=>1])) ?>"><?= $title ?></a><?php endforeach; ?></nav>
    <form method="get" action="<?= sanitize($route) ?>" class="card card-body mb-3"><div class="row g-3">
    <?php foreach(['bank_kind'=>[''=>'All banks','learning'=>'Question Bank','exam'=>'Exam Questions'],'question_group'=>[''=>'All questions','mcq'=>'MCQs','written'=>'Written'],'question_type'=>[''=>'All types',...array_combine(['MCQ','Very Short','Short','Long','Reasoning','Difference Between'],['MCQ','Very Short','Short','Long','Reasoning','Difference Between'])],'status'=>[''=>'All statuses','pending'=>'Pending','corrected'=>'Corrected','rejected'=>'Rejected']] as $key=>$options): ?><div class="col-md-3"><label for="correction_<?= $key ?>" class="form-label"><?= ['bank_kind'=>'Bank','question_group'=>'Question group','question_type'=>'Question type','status'=>'Status'][$key] ?></label><select class="form-select" id="correction_<?= $key ?>" name="<?= $key ?>"><?php foreach($options as $value=>$label): ?><option value="<?= sanitize($value) ?>" <?= $filters[$key]===$value?'selected':'' ?>><?= sanitize($label) ?></option><?php endforeach; ?></select></div><?php endforeach; ?>
    <?php if($admin): foreach(['class_id'=>['Class','SELECT id,name label FROM classes WHERE school_id=0 ORDER BY level,name'],'subject_id'=>['Subject','SELECT DISTINCT s.id,s.name_en label FROM subjects s JOIN class_subjects cs ON cs.subject_id=s.id AND cs.school_id=0 WHERE s.school_id=0'.($filters['class_id']?' AND cs.class_id='.(int)$filters['class_id']:' AND 1=0').' ORDER BY s.name_en,s.id'],'school_id'=>['School','SELECT id,name_en label FROM schools ORDER BY name_en']] as $key=>[$label,$sql]): ?><div class="col-md-3"><label class="form-label" for="correction_<?= $key ?>"><?= $label ?></label><select class="form-select" id="correction_<?= $key ?>" name="<?= $key ?>"><option value="">All <?= strtolower($label) ?>s<?= $key==='subject_id'?' (choose Class first)':'' ?></option><?php foreach($db->query($sql) as $r): ?><option value="<?= (int)$r['id'] ?>" <?= $filters[$key]===(string)$r['id']?'selected':'' ?>><?= sanitize($r['label']) ?></option><?php endforeach; ?></select></div><?php endforeach; endif; ?>
    <div class="col-md-3"><label class="form-label" for="correction_page_size">Per page</label><select class="form-select" id="correction_page_size" name="per_page"><?php foreach([10,20,30,50,100] as $size): ?><option value="<?= $size ?>" <?= $pagination['per_page']===$size?'selected':'' ?>><?= $size ?></option><?php endforeach; ?></select></div><div class="col-md-3 align-self-end"><button class="btn btn-primary">Filter requests</button></div></div></form>
<?php }
